import numpy as np
dirs={'DR':(1,1),'DL':(-1,-1),'UL':(-1,1),'UR':(1,-1),'D':(1,0),'U':(-1,0),'R':(0,1),'L':(0,-1)}
def feasible(p1,p2,H,W):
    res=[]
    s1c=[d for d,v in dirs.items() if (np.sign(v[0]),np.sign(v[1]))==(np.sign(p2[0]-p1[0]),np.sign(p2[1]-p1[1])) and v[0]!=0 or True]
    # allow any s1 first, then s2 perpendicular-ish
    s1c=list(dirs)
    for s1name in s1c:
        for a in range(1, max(H,W)):
            cur=(p1[0]+a*dirs[s1name][0], p1[1]+a*dirs[s1name][1])
            if not(0<=cur[0]<H and 0<=cur[1]<W): break
            for s2name in s1c:
                if s2name==s1name: continue
                v2=dirs[s2name]
                for b in range(1, max(H,W)):
                    cur2=(cur[0]+b*v2[0], cur[1]+b*v2[1])
                    if not(0<=cur2[0]<H and 0<=cur2[1]<W): break
                    # final diag step into p2
                    for fn,fnv in dirs.items():
                        nxt=(cur2[0]+fnv[0], cur2[1]+fnv[1])
                        if nxt==p2 and 0<=nxt[0]<H and 0<=nxt[1]<W:
                            # collect cells excluding endpoints
                            path=set()
                            ok=True
                            for tt in range(1,a+1):
                                ppp=(p1[0]+tt*dirs[s1name][0], p1[1]+tt*dirs[s1name][1])
                                if ppp!=p2: path.add(ppp)
                            for tt in range(1,b+1):
                                qqq=(cur2[0]+tt*v2[0], cur2[1]+tt*v2[1])
                                if qqq!=p2: path.add(qqq)
                            if all(0<=i<H and 0<=j<W for i,j in path):
                                res.append((s1name,a,s2name,b,path))
    return res
